WITH enclosing AS (SELECT COALESCE(p.merged_into_id, p.id) AS project_id, length(rtrim(l.root_path, '/')) AS depth FROM projects.locations l JOIN projects.projects p ON p.id = l.project_id WHERE rtrim(l.root_path, '/') <> '' AND (rtrim(l.root_path, '/') = rtrim('/Users/dawiddutoit/projects/temet/mike', '/') OR starts_with('/Users/dawiddutoit/projects/temet/mike', rtrim(l.root_path, '/') || '/'))), deepest AS (SELECT DISTINCT project_id FROM enclosing WHERE depth = (SELECT max(depth) FROM enclosing)) SELECT p.id, p.project_path FROM deepest d JOIN projects.projects p ON p.id = d.project_id ORDER BY p.id;
